import 'package:cloud_firestore/cloud_firestore.dart';

enum ConsultationStatus { pending, accepted, rejected, active, completed, cancelled }
class ConsultationModel { const ConsultationModel({required this.id, required this.studentId, required this.advisorId, required this.createdAt, this.status = ConsultationStatus.pending, this.subject = '', this.conversationId, this.rating, this.review}); final String id, studentId, advisorId, subject; final DateTime createdAt; final ConsultationStatus status; final String? conversationId, review; final double? rating; factory ConsultationModel.fromFirestore(DocumentSnapshot<Map<String, dynamic>> doc) => ConsultationModel.fromMap(doc.id, doc.data() ?? const {}); factory ConsultationModel.fromMap(String id, Map<String,dynamic> map) => ConsultationModel(id:id, studentId:map['studentId'] as String? ?? '', advisorId:map['advisorId'] as String? ?? '', subject:map['subject'] as String? ?? '', createdAt:(map['createdAt'] as Timestamp?)?.toDate() ?? DateTime.now(), status:ConsultationStatus.values.firstWhere((item)=>item.name==map['status'],orElse:()=>ConsultationStatus.pending), conversationId:map['conversationId'] as String?, rating:(map['rating'] as num?)?.toDouble(),review:map['review'] as String?); Map<String,Object?> toMap()=>{'studentId':studentId,'advisorId':advisorId,'subject':subject,'createdAt':Timestamp.fromDate(createdAt),'status':status.name,'conversationId':conversationId,'rating':rating,'review':review,'updatedAt':FieldValue.serverTimestamp()}; }
